const I64 S_ANG = 1_000_000;
const I64 HALF_PI = 1_570_796;
const I64 PI = 3_141_593;
const I64 TWO_PI = 6_283_185;

// Reduce angle u (in microradians) into [-HALF_PI, HALF_PI] and set sign_flip = -1 or 1.
I64 reduce_sin_angle(I64 u, inout I64[1] sign_flip) {
    I64 r = u % TWO_PI;
    if (r > PI) {
        r = r - TWO_PI;
    }
    sign_flip[0] = 1;
    if (r > HALF_PI) {
        r = PI - r;
    } else if (r < -HALF_PI) {
        r = -PI - r;
        sign_flip[0] = -1;
    }
    return r;
}

// Polynomial sin(x) for x in [-HALF_PI, HALF_PI], scale 1_000_000.
// Measured worst-case error across [0, HALF_PI]: <= 2 microradians (5 digits).
I64 sin_urad(I64 u) {
    I64[1] flip;
    I64 x = reduce_sin_angle(u, flip);
    I64 x2 = muldiv(I64, x, x, S_ANG, half_even);
    // Horner degree-11: ratios 1/(10*11)=110, 1/(8*9)=72, 1/(6*7)=42, 1/(4*5)=20, 1/(2*3)=6
    I64 t = S_ANG - div_round(x2, 110, half_even);
    t = S_ANG - muldiv(I64, x2, t, 72 * S_ANG, half_even);
    t = S_ANG - muldiv(I64, x2, t, 42 * S_ANG, half_even);
    t = S_ANG - muldiv(I64, x2, t, 20 * S_ANG, half_even);
    t = S_ANG - muldiv(I64, x2, t, 6 * S_ANG, half_even);
    return flip[0] * muldiv(I64, x, t, S_ANG, half_even);
}

I64 cos_urad(I64 u) {
    return sin_urad(HALF_PI - u);
}

void main() {
    I64 s0 = sin_urad(0);
    I64 c0 = cos_urad(0);
    I64 s30 = sin_urad(523_599);
    I64 c60 = cos_urad(1_047_198);
    "sin(0)={s0:/1000000} cos(0)={c0:/1000000} sin(pi/6)={s30:/1000000} cos(pi/3)={c60:/1000000}\n";
}

test "pythagorean identity holds within 3 units across quadrant" {
    for k in 0..=15 {
        I64 u = k * 100_000;
        I64 s = sin_urad(u);
        I64 c = cos_urad(u);
        I64 norm = muldiv(I64, s, s, S_ANG, half_even) + muldiv(I64, c, c, S_ANG, half_even);
        assert(abs(norm - S_ANG) <= 3);
    }
}

const I64 SCALE = 1_000_000;
const I64 LN2_SCALED = 693_147;

I64 qsqrt_scaled(I64 x_scaled) {
    I128 wide = (x_scaled as I128) * (SCALE as I128);
    return isqrt_round(wide, half_even) as I64;
}

// Natural log for x_scaled > 0 (where 1.0 == SCALE == 1_000_000).
// Reduces x into [707_106, 1_414_213] by powers of 2, then evaluates 2*artanh((m-1)/(m+1)).
// Measured error on powers of 2 and e: <= 2 units at scale 1_000_000.
I64 qln_scaled(I64 x_scaled) {
    assert(x_scaled > 0);
    I64 m = x_scaled;
    I64 k = 0;
    while (m >= 1_414_214) {
        m = muldiv(I64, m, 1, 2, half_even);
        k += 1;
    }
    while (m < 707_107) {
        m = m * 2;
        k -= 1;
    }
    I64 z = muldiv(I64, m - SCALE, SCALE, m + SCALE, half_even);
    I64 z2 = muldiv(I64, z, z, SCALE, half_even);
    I64 z3 = muldiv(I64, z2, z, SCALE, half_even);
    I64 z5 = muldiv(I64, z3, z2, SCALE, half_even);
    I64 z7 = muldiv(I64, z5, z2, SCALE, half_even);
    I64 series = z + div_round(z3, 3, half_even) + div_round(z5, 5, half_even) + div_round(z7, 7, half_even);
    return k * LN2_SCALED + 2 * series;
}

void main() {
    I64 rt2 = qsqrt_scaled(2_000_000);
    I64 lne = qln_scaled(2_718_282);
    I64 ln10 = qln_scaled(10_000_000);
    "sqrt(2)={rt2:/1000000} ln(e)={lne:/1000000} ln(10)={ln10:/1000000}\n";
}

test "sqrt and ln accuracy" {
    assert(qsqrt_scaled(2_000_000) == 1_414_214);
    assert(qln_scaled(SCALE) == 0);
    assert(abs(qln_scaled(2_718_282) - SCALE) <= 2);
    assert(abs(qln_scaled(10_000_000) - 2_302_585) <= 2);
}

// In cint 0.2.0, muldiv operands and result type must match width (SPEC-09P.1 12.1).
// Widen I64 values to I1024 with `as I1024` first, then call muldiv(I1024, ...).

I1024 scale_1e30() {
    I1024 ten15 = 1_000_000_000_000_000 as I1024;
    return ten15 * ten15;
}

I1024 harmonic_sum_scaled(I64 n) {
    I1024 s = scale_1e30();
    I1024 total = 0 as I1024;
    for k in 1..=n {
        total = total + muldiv(I1024, s, 1 as I1024, k as I1024, half_even);
    }
    return total;
}

void main() {
    I1024 h20 = harmonic_sum_scaled(20);
    "H_20 * 10^30 = {h20}\n";
}

test "exact I1024 harmonic sum for n=4" {
    // H_4 = 1 + 1/2 + 1/3 + 1/4 = 25/12 = 2.083333333333333333333333333333...
    I1024 s = scale_1e30();
    I1024 expected = muldiv(I1024, s, 25 as I1024, 12 as I1024, half_even);
    assert(harmonic_sum_scaled(4) == expected);
}

const I64 S = 1_000;

void main() {
    I64 x = 80_000;
    I64 y = 0;
    I64 vx = 0;
    I64 vy = 60_000;
    "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"-100 -100 200 200\">\n";
    "  <polyline fill=\"none\" stroke=\"#111111\" stroke-width=\"1.5\" points=\"";
    for step in 0..8 {
        if (step > 0) {
            " ";
        }
        "{x:/1000},{y:/1000}";
        // Symplectic Euler step: a = -k * x
        I64 ax = -muldiv(I64, x, 100, S, half_even);
        I64 ay = -muldiv(I64, y, 100, S, half_even);
        vx = vx + ax;
        vy = vy + ay;
        x = x + muldiv(I64, vx, 200, S, half_even);
        y = y + muldiv(I64, vy, 200, S, half_even);
    }
    "\"/>\n</svg>\n";
}

test "symplectic step deterministic coordinates" {
    I64 x = 80_000;
    I64 ax = -muldiv(I64, x, 100, S, half_even);
    assert(ax == -8_000);
}

const U64 FNV_OFFSET = 0xcbf29ce484222325;
const U64 FNV_PRIME = 0x100000001b3;

U64 fnv1a_word(U64 h, I64 word) {
    U64 u = word as% U64;
    U64 acc = h;
    for b in 0..8 {
        U64 byte_val = u & 0xff;
        acc = (acc ^ byte_val) *% FNV_PRIME;
        u = u >> 8;
    }
    return acc;
}

U64 fnv1a_slice[n](in I64[n] vals) {
    U64 h = FNV_OFFSET;
    for i in 0..n {
        h = fnv1a_word(h, vals[i]);
    }
    return h;
}

void main() {
    I64[3] state;
    state[0] = 1_000_000;
    state[1] = -250_000;
    state[2] = 42;
    U64 d = fnv1a_slice(state);
    "digest={d:#018x}\n";
}

test "fnv1a byte-wise digest is deterministic" {
    I64[2] a;
    a[0] = 1;
    a[1] = -1;
    assert(fnv1a_slice(a) == 0xc4777a6e69ba809c);
}

const I64 DEPOSIT = 0;
const I64 WITHDRAW = 1;

error LedgerError { overdrawn, invalid_kind }

struct Entry {
    I64 kind;
    I64 cents;
}

I64 daily_interest(I64 balance_cents, I64 rate_bps) {
    return muldiv(I64, balance_cents, rate_bps, 3_650_000, half_even);
}

LedgerError!I64 apply_entry(I64 balance, Entry e) {
    switch (e.kind) {
        case 0: {
            return balance + e.cents;
        }
        case 1: {
            if (e.cents > balance) {
                return .overdrawn;
            }
            return balance - e.cents;
        }
        default: {
            return .invalid_kind;
        }
    }
}

LedgerError!void main() {
    Entry[2] book;
    book[0] = Entry(DEPOSIT, 125_000);
    book[1] = Entry(WITHDRAW, 40_050);
    I64 bal = 0;
    for i in 0..2 {
        bal = try apply_entry(bal, book[i]);
    }
    I64 interest = daily_interest(bal, 450);
    bal = bal + interest;
    "balance={bal:/100} interest={interest:/100}\n";
}

test "banker's rounding ties to even" {
    assert(daily_interest(1_825_000, 1) == 0);
    assert(daily_interest(5_475_000, 1) == 2);
}

test "overdraft returns error value" {
    I64 bal = apply_entry(100, Entry(WITHDRAW, 101)) catch -1;
    assert(bal == -1);
}

test "deposit overflow raises E_OVERFLOW" expect_fault E_OVERFLOW {
    _ = apply_entry(I64.max, Entry(DEPOSIT, 1));
}

kernel step_and_sum[n](in I64[n] src, out I64[n] dst, in I64 gain, out I64 total)
    over [i: n]
{
    I64 v = src[i] * gain + 1;
    dst[i] = v;
    reduce total = sum(v);
}

void main() {
    I64[4] buf_a;
    I64[4] buf_b;
    buf_a[0] = 10;
    buf_a[1] = 20;
    buf_a[2] = 30;
    buf_a[3] = 40;
    I64 sum1 = 0;
    I64 sum2 = 0;
    // Dispatch 0: read buf_a, write buf_b (disjoint storage -> no C5010 / E_ALIAS)
    step_and_sum(buf_a, buf_b, 2, sum1);
    // Dispatch 1: read buf_b, write buf_a
    step_and_sum(buf_b, buf_a, 3, sum2);
    "sum1={sum1} sum2={sum2} final=[{buf_a[0]}, {buf_a[1]}, {buf_a[2]}, {buf_a[3]}]\n";
}

test "double buffer kernel matches sequential sum" {
    I64[4] a;
    I64[4] b;
    a[0] = 1;
    a[1] = 2;
    a[2] = 3;
    a[3] = 4;
    I64 total = 0;
    step_and_sum(a, b, 10, total);
    assert(total == 104);
    assert(b[3] == 41);
}

chunks.content:
A source file whose statements stand at its top level is a *script*, and its statements run in order. In the examples, a string on a line of its own is a print statement: it writes the string, with each `{...}` replaced by the value of the expression inside. Here are the four spellings of one sum of two `U8` values, whose range is 0 to 255:

```cint forms.ci
// forms.ci: one sum of two U8 values, in each spelling.
U8 a = 200;
U8 b = 100;
"wrapping:   {a +% b}\n";
"saturating: {a +| b}\n";
U8 c = add_result(a, b) catch 0;
"result:     {c}\n";
"checked:    {a + b}\n";
```

```text
wrapping:   44
saturating: 255
result:     0
fault[E_OVERFLOW]: the exact result is outside the type's range
  --> forms.ci:8:17
   |
 8 | "checked:    {a + b}\n";
   |                 ^ add.checked.u8
   |
   = operation: add.checked.u8
   = operand-count: 2
   = operand: U8 200
   = operand: U8 100
   = exact:   300
   = limit:   U8 255
...
```

The exact sum is 300. It wraps to 44 and saturates at 255, and `add_result` gives the error `ArithError.overflow`, which `catch 0` replaces with 0. The checked `+` faults, and its print statement writes nothing. A line `...` in shown output stands for lines left out.

Two types in one sum are rejected before the program runs:

```cint mixed.ci
// mixed.ci: an I32 and an I64 in one sum.
I32 a = 5;
I64 b = 7;
"{b + a}\n";
```

```text
error[C2001]: type mismatch
  --> mixed.ci:4:7
   |
 4 | "{b + a}\n";
   |       ^
```

A conversion of one operand fixes it: `b + (a as I64)`.

## 2 A first program

Functions are declared as in C. This script computes two factorials in `I64`:

```cint factorial.ci
// factorial.ci: n! computed in I64.
I64 factorial(I64 n) {
    I64 f = 1;
    for k in 1..=n {
        f = f * k;
    }
    return f;
}

"10! = {factorial(10)}\n";
"20! = {factorial(20)}\n";
```

`cint run factorial.ci` prints:

```text
10! = 3628800
20! = 2432902008176640000
```

`cint run` compiles the script to C, builds it and runs it. `for k in 1..=n` runs its body for each `k` from 1 through `n`.

The factorial of 21, 51090942171709440000, does not fit in `I64`. A third line asks for it:

```cint factorial21.ci
// factorial21.ci: one step past the largest factorial I64 holds.
I64 factorial(I64 n) {
    I64 f = 1;
    for k in 1..=n {
        f = f * k;
    }
    return f;
}

"10! = {factorial(10)}\n";
"20! = {factorial(20)}\n";
"21! = {factorial(21)}\n";
```

```text
10! = 3628800
20! = 2432902008176640000
fault[E_OVERFLOW]: the exact result is outside the type's range
  --> factorial21.ci:5:15
   |
 5 |         f = f * k;
   |               ^ mul.checked.i64
   |
   = operation: mul.checked.i64
   = operand-count: 2
   = operand: I64 2432902008176640000
   = operand: I64 21
   = exact:   51090942171709440000
   = limit:   I64 9223372036854775807
...
   = stack-depth: 1
   = called from: factorial21.ci:12:9
   = fuel-consumed: 55 (not part of the fault record)
   = state: the program stopped; stdout holds what it wrote before the fault
```

The program wrote two lines. The third print statement wrote nothing, because the expression inside its `{...}` faulted. The report, on the standard error, reads:

## 5 What 0.2.0 includes and what it does not

The language of cint 0.2.0 is what SPEC-04P.2 states and the reference runs:

- the integer types from `I8` to `I1024` and from `U8` to `U512`, the fixed-point types, `Bool`, structs, error sets and error unions;
- the checked, wrapping and saturating operators, the result forms, the conversions `as`, `as%` and `as?` and the built-in operations of SPEC-04P.2 clause 7, such as `muldiv`, `div_round` and `sum`;
- variables and constants; functions with `in` and `inout` parameters; `if`, `while`, `for` over a range, `switch`, labeled `break` and `continue`, `defer` and `errdefer`, `assert`, and print statements with format specifications;
- arrays and views of rank 1 to 4, with checked indexing and slicing; kernels and their reductions; arenas, pools and handles;
- scripts, programs with `main`, importable modules with imports and exports and tests.

The tools of cint 0.2.0 are the `cint` command with `run`, `build`, `test` and `emit-c`; the interpreter, `cint interp`; `cint workbench`, `cint explain` and `cint debug`; the C interface and the Python module of SPEC-03P.1; and the reference.

The `cint` command of 0.2.0 does not build every construct that the reference runs. For such a construct it reports, when it translates the program, a refusal diagnostic such as C9102, and it does not run the program with another meaning. On an implementation that runs the construct, its meaning is the one SPEC-04P.2 states. SPEC-09P.1 clause 12 lists each refused construct with its code and position, and the operations that `gpu-cuda` refuses in a kernel with the fault `E_UNSUPPORTED`.

## 6 Finding out why

When a program faults, or prints something unexpected, SPEC-04P.2 clause 8 shows how to find out why. This section is a short tour of it, with the programs of section 2 and this module:

```cint
// fact.ci: n! in I64, as a module with two tests.
export I64 factorial(I64 n) {
    I64 f = 1;
    for k in 1..=n {
        f = f * k;
    }
    return f;
}

test "20! fits in I64" {
    assert(factorial(20) == 2432902008176640000);
}

test "21! does not" expect_fault E_OVERFLOW {
    _ = factorial(21);
}
```

`fact.ci` has only declarations, so it is an *importable module*, which runs nothing by itself. `export` lets code outside the module call `factorial`, and each `test` block states one expectation about it (SPEC-04P.2 5.1.2, 6.15).

## Introduction

A fault has a text form and a machine form. The text form is the fault report; the machine form is the *fault record*: a sequence of bytes, fixed field by field, that every conforming implementation produces identically for the same fault. This program withdraws more than its balance holds, and the conversion of the negative balance to `U8` faults:

```cint ledger.ci
I64 balance = 100;

void withdraw(I64 amount) {
    balance -= amount;
    U8 rest = balance as U8;
    "rest {rest}\n";
}

void main() {
    withdraw(30);
    withdraw(80);
}
```

```text
rest 70
fault[E_NARROW]: the value does not fit the destination type
  --> ledger.ci:5:23
   |
 5 |     U8 rest = balance as U8;
   |                       ^ as.checked.i64.u8
   |
   = operation: as.checked.i64.u8
   = operand-count: 1
   = operand: I64 -10
   = exact:   -10
   = limit:   U8 0
   ...
```

The record of this fault is 151 bytes. It begins with the string `cint-core-1/fault/v2`, preceded by its length, which names the encoding and its version. The code `E_NARROW` follows as the number 6, then the operation identifier, the operand `I64 -10` as a type tag and eight bytes, the exact result, the limit, the position, the revision of the program and the stack. Subclause 6.2 shows every byte.

## 1 Scope

1. This document specifies the canonical byte encodings of cint 0.2.0, for the language profile `cint-core-1`:
   - values of the types of SPEC-04P.2 6.3 that an encoding holds, and mathematical integers;
   - fault records, and the records of fuel consumed and of an error result that a compiled program writes for the `cint` command;
   - the state of a program, the checkpoint that holds it and the state hash;
   - recordings and cases;
   - the revision identity, the source-map digest and the inputs of execution identity;
   - the operation fixture format CIF-1.
2. This document does not specify:
   - the meaning of values, operators, faults and fuel, which SPEC-04P.2 specifies;
   - the text of fault reports and diagnostics, and the JSON forms that the tools print, which SPEC-04P.2 8.1 and SPEC-06P.1 specify;
   - the canonical SIR text over which the revision identity is computed, the conformance suite and its `.expect` format, which SPEC-09P.1 specifies;
   - the C and Python interfaces through which a host program creates contexts, takes checkpoints and records runs, which SPEC-03P.1 specifies;
   - the files of a saved workbench session, which SPEC-06P.1 specifies.

### 5.5 Decoding values

A decoder of any encoding of this document reads tagged values and payloads by the same rules, and rejects bytes that are not a canonical value.

**Constraints**

1. A decoder rejects, before it allocates memory for a payload [IM-148]:
   - a tag that 5.4 does not define, or one that the field does not allow;
   - a `Bool` byte other than `00` and `01`, including a `Bool` element of an array or a struct;
   - a Z whose bytes are not minimal (5.3), or whose length is above the bound of its field and record (6.3);
   - a fixed-point tag whose storage tag is not `11` to `14`, or whose `f` is above `w - 1`;
   - an array of rank 0 or above 8, with a negative extent, or whose payload size is above `I64.max` or differs from the bytes that remain;
   - a handle of a kind above `02`, or a null handle with a byte that is not `00`;
   - a struct tag with a definition that is missing, a name that is empty or not UTF-8, a layout or bit width other than `00`, an array field of rank 0 or above 4 or with another form or size symbol, a reference to its own definition or to one after it, a type that is not the last definition, or a payload whose size differs from the bytes that remain;
   - a length or count larger than the bytes that remain.

1. <a id="IM-149"></a>The code is the number of the record's fault code, from 1 for `E_OVERFLOW` to 13 for `E_ASSERT`, as the table of SPEC-04P.2 5.2.3 gives it [IM-149] [SPEC-04P.2 IM-104].
2. The operation identifier has 1 to 64 bytes, each a lowercase letter, a digit, `.` or `_`. There are at most 8 operands, each a tagged value of a tag that 5.4 allows for an operand [IM-149] [SPEC-04P.2 IM-106].
3. `exact`, when present, is a tagged Z [IM-149].
4. The path of a position has 1 to 1024 bytes of UTF-8, and its line and column are at least 1 [IM-149] [SPEC-04P.2 IM-106].
5. An absent revision, source-map digest or address is a presence byte `00`, never 32 zero bytes or another placeholder [IM-149].
6. The kernel name of an address has at most 256 bytes of UTF-8, and its phase is 0, 1 or 2. The work-item field is present when the phase is 1 and absent otherwise [IM-149].
7. The stack has fewer positions than the entry's call-depth limit, and a decoder rejects a stack of more than 1024 positions [IM-149] [SPEC-04P.2 IM-106].

**Semantics**

8. The bytes of a record are a function of its content alone: the writer takes no padding, alignment or other byte from the structure in memory that holds the record, and conformance compares the bytes, never the structure [IM-149] [SPEC-09P.1 RT-13, RT-14].
9. cint 0.2.0 writes the source-map digest of every fault record as absent. A recording or a case holds the source-map digest of its program in its header (8.2), which names the positions of every record it holds.

**Examples**

10. A fault inside a kernel has an address:

```cint kern.ci
kernel bump[n](in I64[n] old, out I64[n] next) {
    next = old + 1;
}

void main() {
    I64[3] a = [1, 2, 9223372036854775807];
    I64[3] b;
    bump(a, b);
    "{b[0]}\n";
}
```

### 6.4 Record kinds and decoding

A decoder of a fault record is told the record's kind by its caller, because the same bytes are bounded differently at run time and at compile time.

**Constraints**

1. A decoder is given the record kind with the bytes, which do not carry it: compile-time for a record that a compiler reports with a diagnostic of a faulting constant, run-time for a record of an entry, including every record held in a state, a checkpoint or a recording. A record decoded under the wrong kind is rejected when a field is above that kind's bound [IM-148, IM-149].
2. A decoder rejects, besides the values of 5.5 [IM-148]:
   - a domain string other than the two of 6.1;
   - a code outside 1 to 13, an operation identifier that is empty, longer than 64 bytes or has another character, or more than 8 operands;
   - an `exact` that is not a Z;
   - a run-time record of version 3 whose operation does not begin with `dot.checked.i1024.`, and one of version 2 whose operation does;
   - a version 3 record decoded with the compile-time kind;
   - a position whose path is empty, longer than 1024 bytes or not UTF-8, or whose line or column is 0;
   - an address whose phase is above 2, or with a work item outside phase 1;
   - a stack of more than 1024 positions;
   - bytes after the last position of the stack, when the record is a file of its own.

### 8.7 Decoding a recording

**Constraints**

1. A decoder checks a whole recording before any part of it is used, and refuses it entirely when a check fails [SPEC-03P.1 H-14, H-17a]:
   - the header (8.2), the code (8.3), the initial checkpoint (7.5) and every checkpoint of a restore event;
   - that the revision of the initial checkpoint is the revision of the header;
   - the source-map digest of the header and of each revision event against its code;
   - the order and fields of every event (8.4), and each outcome against its entry;
   - the digest chain and the event count against the end event;
   - that the file ends with the end event: a file without one is incomplete and is never loaded in part.

### 9.4 What never enters an identity

**Semantics**

1. The revision depends only on the profile, the runtime contract version and the position-free SIR text of each module with its module-relative path. The directory a tool runs in, the absolute path of a file, the time, the time zone, the locale, the environment, the executor, the C compiler and the host do not enter it [IM-157] [SPEC-03P.1 H-15].
2. The build identity, the payload digest and the build record digest are separate fields of the checkpoint envelope; they enter neither the revision nor the state hash. Executables of one program built for different executors or machines, under one runtime contract version, have one revision [SPEC-03P.1 H-15].
3. State holds no time, locale, path outside a module-relative path, native address, thread identifier or backend name, so neither does a state hash [IM-151].

**Examples**

