const I64 B = div_round(7, 2, half_even);
const I8 C = I8.max;
const I64 D = abs(-5) + isqrt(50);
const U8 E = 200 +| 100;
const I64 F = (300 as% U8) as I64;
"{A} {B} {C} {D} {E} {F}\n";
```

```text
3 4 127 12 255 44
```

