E!I64 root_floor(I64 x) {
    if (x < 0) {
        return .negative;
    }
    return isqrt(x);
}

I64 total = 0;
for i in -2..3 {
    I64 r = root_floor(i * 5) catch (e) {
        "skip {i}\n";
        continue;
    };
    total += r;
}
"{total}\n";
```

```text
