## division in cint

**`/` rounds toward negative infinity**, and `%` takes the sign of the divisor. Together they keep `a == (a / b) * b + a % b` for every division that does not fault. This is Python's rule, not C's.

```ci
void main() {
    I64 a = -7;
    I64 b = 2;
    "a / b      = {a / b}   a % b      = {a % b}\n";
    "div_trunc  = {div_trunc(a, b)}   rem_trunc  = {rem_trunc(a, b)}\n";
    "div_euclid = {div_euclid(a, b)}   rem_euclid = {rem_euclid(a, b)}\n";
    "floor {div_round(a, b, floor)}  ceil {div_round(a, b, ceil)}  trunc {div_round(a, b, trunc)}  away {div_round(a, b, away)}\n";
    "half_even {div_round(a, b, half_even)}  half_away {div_round(a, b, half_away)}  half_trunc {div_round(a, b, half_trunc)}  half_up {div_round(a, b, half_up)}  half_down {div_round(a, b, half_down)}\n";
}
```

```text
a / b      = -4   a % b      = 1
div_trunc  = -3   rem_trunc  = -1
div_euclid = -4   rem_euclid = 1
floor -4  ceil -3  trunc -3  away -4
half_even -4  half_away -4  half_trunc -3  half_up -3  half_down -4
```

- `div_trunc` and `rem_trunc` are C's division: toward zero.
- `div_euclid` and `rem_euclid` keep the remainder between 0 and `|b| - 1`.
- `div_round(a, b, mode)` rounds the exact quotient, -3.5 here, by a named mode. There are nine modes. Four round in one direction: `floor`, `ceil`, `trunc` and `away`. Five round to the nearest integer and differ only on ties: `half_even`, `half_away`, `half_trunc`, `half_up` and `half_down`.

Division by zero faults with `E_DIV_ZERO`. `I64.min / -1`, whose exact result is one past `I64.max`, faults with `E_OVERFLOW`.

## the program

This is the bill split from [201-04](04-division-and-rounding.md), with its two calculations as functions and three tests at the end of the file:

```ci
// Split a bill in cents among people, with an 18 percent tip.
// The cents that do not divide evenly go to the first people, one each.

I64 tip(I64 bill) {
    return muldiv(I64, bill, 18, 100, half_even);
}

// What person p (counting from 1) pays when total is split among people.
I64 share(I64 total, I64 people, I64 p) {
    I64 pays = total / people;
    if (p <= total % people) {
        pays += 1;
    }
    return pays;
}

void main() {
    I64 bill = 10_000;
    I64 total = bill + tip(bill);
    I64 people = 3;
    "bill {bill:/100}, tip {tip(bill):/100}, total {total:/100}\n";
    for p in 1..=people {
        "person {p} pays {share(total, people, p):/100}\n";
    }
}

test "the shares add up to the total" {
    for people in 1..=12 {
        I64 paid = 0;
        for p in 1..=people {
            paid += share(11_800, people, p);
        }
        assert(paid == 11_800);
    }
}

test "a tip of half a cent rounds to even" {
    assert(tip(25) == 4);       // 4.5 cents rounds to 4
    assert(tip(75) == 14);      // 13.5 cents rounds to 14
}

test "nobody to split among is a fault" expect_fault E_DIV_ZERO {
    _ = share(100, 0, 1);
}
```

## the module

Save this as `savings.ci`:

```ci
// savings.ci: a savings balance in cents, with interest paid daily.

export I64 balance = 100_000;   // 1000.00

I64 daily_interest(I64 cents, I64 basis_points) {
    return muldiv(I64, cents, basis_points, 10_000 * 365, half_even);
}

// One day: add a day's interest at a yearly rate in basis points.
export void day(I64 basis_points) {
    balance += daily_interest(balance, basis_points);
}
```

Every cint file is a module. This one has no `main`, so it does nothing on its own: other code uses what it exports. `balance` and `day` are exported; `daily_interest` is not. A basis point is a hundredth of a percent, so 450 basis points is 4.50 percent a year.

## the program

Adler-32 is the checksum inside every zlib stream, including the image data of PNG files. It keeps two sums, `a` and `b`, and takes both remainders by 65,521 after every byte:

```ci
// adler.ci: the Adler-32 checksum, which zlib and PNG files use.

const U32 MOD = 65_521;

U32 adler32[n](in U8[n] data) {
    U32 a = 1;
    U32 b = 0;
    for i in 0..n {
        a = (a + (data[i] as U32)) % MOD;
        b = (b + a) % MOD;
    }
    return (b << 16) | a;
}

void main() {
    U8[20_000] letters;
    U8[20_000] high;
    for i in 0..20_000 {
        letters[i] = 97;    // the letter a
        high[i] = 255;      // the largest byte
    }
    U32 w = adler32("Wikipedia");
    "Wikipedia     {w:x}\n";
    U32 l = adler32(letters);
    "20000 a       {l:x}\n";
    U32 h = adler32(high);
    "20000 x 255   {h:x}\n";
}
```

```text
$ cint run adler.ci
Wikipedia     11e60398
20000 a       62f99bd4
20000 x 255   9f51d664
```

Python's `zlib.adler32` gives the same three values.

## step 3: one change

zlib does not take the remainders after every byte. It adds up a block of bytes first and takes the remainders once per block, which saves work. Replace `adler32` with this version:

```ci
// Take the remainders once per block, not once per byte. zlib uses
// 5552, the largest block after which b still fits in a U32.
const I64 BLOCK = 5_552;

U32 adler32[n](in U8[n] data) {
    U32 a = 1;
    U32 b = 0;
    I64 start = 0;
    while (start < n) {
        I64 end = start + BLOCK;
        if (end > n) {
            end = n;
        }
        for i in start..end {
            a += data[i] as U32;
            b += a;
        }
        a %= MOD;
        b %= MOD;
        start = end;
    }
    return (b << 16) | a;
}
```

Run it into a new file and compare:

```text
$ cint run adler.ci > after.txt
$ diff golden.txt after.txt
$ python3 -m cint_ref check adler.ci adler.expect
adler.expect: line 6 differs
  expected: fuel-consumed 60013
  actual:   fuel-consumed 60022
```

The output matches the golden. The record shows that the path changed, which is what the change was for. The first version takes two remainders for every byte, 80,018 in all, and the block version takes two for every block, 18 in all. Fuel is charged at each call and at each pass through a loop, not for each operation, so the block version's 9 passes through `while` add 9. Fuel measures the path a run takes, not its speed. Save the new record in a step of its own.

## the program

The Collatz rule halves an even number and turns an odd number n into 3n + 1. Every positive whole number checked so far reaches 1 when the rule is repeated, and nobody has proved that all do. This program counts the steps:

```ci
// Collatz paths: the steps a start takes to reach 1,
// halving each even number and tripling each odd one, plus one.

I64 next(I64 n) {
    if (n % 2 == 0) {
        return n / 2;
    }
    return 3 * n + 1;
}

I64 steps_to_one(I64 start) {
    I64 n = start;
    I64 taken = 0;
    while (n != 1) {
        n = next(n);
        taken++;
    }
    return taken;
}

void main() {
    // Starts 1, 10, 100, 1000: the range form has no step, so this is a C-form loop.
    for (I64 start = 1; start <= 1_000; start *= 10) {
        "{start:>4} takes {steps_to_one(start)} steps\n";
    }

    // Sort the starts below 1000 by how long they take.
    I64 quick = 0;
    I64 middling = 0;
    I64 slow = 0;
    for start in 1..1_000 {
        switch (steps_to_one(start)) {
            case 0..=19:
                quick++;
            case 20..=99:
                middling++;
            default:
                slow++;
        }
    }
    "below 1000: {quick} quick, {middling} middling, {slow} slow\n";

    // The first start whose path climbs past 100,000.
    I64 found = 0;
    I64 first_over = 0;
    starts: for start in 1..1_000 {
        I64 n = start;
        while (n != 1) {
            n = next(n);
            if (n > 100_000) {
                found = start;
                first_over = n;
                break starts;
            }
        }
    }
    "first past 100000: {found}, first goes over 100000 at {first_over}\n";
}
```

## `if` and `while`

`if`, `else if`, `else` and `while` read as they do in C, with one rule C does not have: every body needs its braces, even a body of one statement.

```ci
void main() {
    I64 c = 3;
    if (c > 2) "big\n";
}
```

```text
error[C1043]: missing parentheses or braces
  --> braces.ci:3:16
   |
 3 |     if (c > 2) "big\n";
   |                ^
   |
```

An assignment is a statement, not a value, so `if (x = 5)` is an error where C would assign and test:

```ci
void main() {
    I64 x = 3;
    if (x = 5) {
        "five\n";
    }
}
```

```text
error[C1041]: assignment in a condition
  --> assign.ci:3:9
   |
 3 |     if (x = 5) {
   |         ^
   |
```

`taken++;` is a statement too, and a checked one: at the largest value of its type it faults. It cannot appear inside an expression, so `a[i++]` is an error. cint 0.2.0 has no `do`-`while` loop; write a `while` loop instead.

## `switch`

A `switch` tests one integer against cases. Each case holds constants, ranges written with `..=` or a list of both, such as `case 1..=4, 9:`. A case's body ends at the next `case`, so the program's three counters never mix. Where one body should go on into the next, it says so with `fallthrough;`:

```ci
I64 code = 6;
switch (code) {
    case 0:
        "ok\n";
    case 1..=4, 9:
        "warning {code}\n";
    case 5..=8:
        "error {code}\n";
        fallthrough;
    case 10:
        "logged\n";
    default:
        "unknown {code}\n";
}
```

This prints `error 6` and then `logged`.

Four `switch` mistakes are errors:

| Written | Error | Why |
|---|---|---|
| `case 1:` with no body, followed by `case 2:` | C4023 | This is C's way to share a body. Write `case 1, 2:`. |
| `case 1..5:` | C4022 | A case range must include its end, so it is written `1..=5`. |
| a `switch` that leaves out some values | C4020 | Every value must have a case, or the `switch` needs a `default`. |
| the same value in two cases | C4021 | Only one case may claim a value. This is an error in C too. |

`break;` inside a `switch` leaves the `switch`, as in C.

## the program

The harmonic number H(n) is 1 + 1/2 + 1/3 + ... + 1/n. This program adds it up as an exact fraction and keeps the fraction in lowest terms with Euclid's algorithm:

```ci
// Exact sums of fractions, reduced with Euclid's algorithm.

// Euclid: gcd(a, b) is gcd(b, a % b), and gcd(a, 0) is a.
I64 gcd(I64 a, I64 b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

// Add 1/k to the fraction f[0]/f[1] and reduce it to lowest terms.
void add_unit(inout I64[2] f, I64 k) {
    I64 num = f[0] * k + f[1];
    I64 den = f[1] * k;
    I64 g = gcd(num, den);
    f[0] = num / g;
    f[1] = den / g;
}

void main() {
    "gcd(1071, 462) = {gcd(1071, 462)}\n";
    I64[2] h;
    h[0] = 0;
    h[1] = 1;
    for k in 1..=50 {
        add_unit(h, k);
        if (k % 10 == 0) {
            "H({k}) = {h[0]}/{h[1]}\n";
        }
    }
}
```

## a smaller way to add

The program multiplies both denominators together and only then divides out the common part, so its numbers grow faster than the answer does. Adding over the least common denominator keeps them smaller. Replace `add_unit` with this version:

```ci
// Add 1/k to the fraction f[0]/f[1], over the least common denominator.
void add_unit(inout I64[2] f, I64 k) {
    I64 den = f[1] / gcd(f[1], k) * k;
    I64 num = f[0] * (den / f[1]) + den / k;
    I64 g = gcd(num, den);
    f[0] = num / g;
    f[1] = den / g;
}
```

It gets three numbers further and faults while adding 1/47:

```text
fault[E_OVERFLOW]: the exact result is outside the type's range
  --> harmonic.ci:13:35
   |
13 |     I64 den = f[1] / gcd(f[1], k) * k;
   |                                   ^ mul.checked.i64
   |
   = operation: mul.checked.i64
   = operand-count: 2
   = operand: I64 1345655451257488800
   = operand: I64 47
   = exact:   63245806209101973600
   = limit:   I64 9223372036854775807
   ...
```

This time the `exact` line is the answer itself. 63245806209101973600 is the denominator of H(47), and it does not fit in an `I64`. No way of arranging the arithmetic can hold H(47) in this type. A wider type can hold it, and [301-04](../301/04-big-exact-numbers.md) carries the sum to H(100) in `I256`.

## recursion and the depth limit

`gcd` calls itself until `b` is 0. Euclid's algorithm takes at most five steps for each decimal digit of the smaller number, so for any two `I64` values it calls itself fewer than 100 times.

Every program has a limit on how deep calls can go: 256 calls in progress at once, counting `main`. A recursion that goes deeper faults with `E_DEPTH`:

```ci
I64 sum_to(I64 n) {
    if (n == 0) {
        return 0;
    }
    return n + sum_to(n - 1);
}
void main() {
    "{sum_to(100)}\n";
    "{sum_to(100_000)}\n";
}
```

`sum_to(100)` returns 5050, and `sum_to(100_000)` faults. `sum_to(254)` is the largest call that runs without a fault.

```text
fault[E_DEPTH]: call depth limit exceeded
  --> deep.ci:5:16
   |
 5 |     return n + sum_to(n - 1);
   |                ^ call.enter
   |
   = operation: call.enter
   = operand-count: 0
   = exact:   none
   = limit:   I64 256
   ...
   = stack-depth: 255
   = called from: deep.ci:9:7
   = called from: deep.ci:5:16
   ...
```

`main` counts as one of the 256, so `stack-depth` stops at 255, and the report lists those 255 calls, with one `called from` line for each. A loop computes the same sum without adding to the call depth. Recursion suits work that shrinks by at least half every step or two, such as Euclid's algorithm or a binary search, because then the depth grows with the number of digits and not with the number itself.

## the program

Fermat's test checks whether a number m could be prime. If m is an odd prime, then 2 to the power m - 1, divided by m, leaves a remainder of 1. A remainder other than 1 proves that m is not prime: it is composite, a product of smaller numbers. The power is far too large to compute, so the program keeps only the remainder after each multiplication:

```ci
// Fermat's test: if m is prime, then 2 to the power m - 1,
// divided by m, leaves 1. A remainder other than 1 proves m composite.

// a * b % m, for a and b below m.
I64 mul_mod(I64 a, I64 b, I64 m) {
    return a * b % m;
}

// base to the power exp, modulo m, by repeated squaring.
I64 pow_mod(I64 base, I64 exp, I64 m) {
    I64 result = 1;
    I64 b = base % m;
    I64 e = exp;
    while (e > 0) {
        if (e % 2 == 1) {
            result = mul_mod(result, b, m);
        }
        b = mul_mod(b, b, m);
        e /= 2;
    }
    return result;
}

void main() {
    I64[3] tests = [1_000_000_007, 2_305_843_009_213_693_951, 2_305_843_009_213_693_953];
    for i in 0..3 {
        I64 m = tests[i];
        "{m:>19}: remainder {pow_mod(2, m - 1, m)}\n";
    }
}
```

The first number, 1000000007, is a prime often used in programming contests. The second is 2<sup>61</sup> - 1, which is also prime. The third is 2<sup>61</sup> + 1, which 3 divides.

## the program

The factorial of n, written `n!`, multiplies every whole number from 1 to n. The binomial coefficient "n choose k" counts the ways to pick k things from n: there are 2598960 different five-card hands in a deck of 52. Both grow far past `I64`:

```ci
// Big exact numbers: factorials, binomial coefficients and a digit count.

// n factorial, exact in I1024.
I1024 factorial(I64 n) {
    I1024 f = 1;
    for k in 1..=n {
        f *= k as I1024;
    }
    return f;
}

// n choose k: the number of ways to pick k things from n.
I1024 choose(I64 n, I64 k) {
    I1024 c = 1;
    for i in 1..=k {
        c = c * ((n - k + i) as I1024) / (i as I1024);
    }
    return c;
}

// The number of decimal digits in x, for x above 0.
I64 digits(I1024 x) {
    I1024 rest = x;
    I64 n = 0;
    while (rest > 0) {
        rest /= 10;
        n += 1;
    }
    return n;
}

void main() {
    I1024 f = factorial(100);
    "100! = {f}\n";
    "100! has {digits(f)} digits\n";
    "52 choose 5 = {choose(52, 5)}\n";
    "100 choose 50 = {choose(100, 50)}\n";
    "170! has {digits(factorial(170))} digits\n";
    "171! has {digits(factorial(171))} digits\n";
}
```

## try this

1. Print 100 choose k for k from 0 to 100. Which k gives the largest value?
2. Add the digits of `100!` together. A parameter cannot be assigned, so work on a copy, as `digits` does. What is the sum?
3. Write a loop that multiplies an `I512` by 1, 2, 3 and so on, printing each number after it multiplies, until it faults. Which is the largest factorial an `I512` holds?

<details>
<summary>answer to 2</summary>

The digits of `100!` add up to 648. This is one way, for x above 0:

```ci
I64 digit_total(I1024 x) {
    I1024 rest = x;
    I64 total = 0;
    while (rest > 0) {
        total += (rest % 10) as I64;
        rest /= 10;
    }
    return total;
}
```

`rest % 10` is an `I1024` between 0 and 9, so converting it to `I64` cannot fault. A local called `sum` would be refused, because `sum` is the name of a built-in function.
</details>

## the program

```ci
// ledger.ci: an exact bank ledger. Money is whole cents in I64.

error LedgerError { overdrawn, unknown_kind }

// The kinds of entry, as typed constants.
const U8 DEPOSIT = 0;
const U8 WITHDRAW = 1;
const U8 INTEREST = 2;

struct Entry {
    U8 kind;
    I64 cents;                  // the amount; for interest, the yearly rate in basis points
}

// One day of interest at a yearly rate in basis points, rounded half to even, to the cent.
I64 daily_interest(I64 balance, I64 basis_points) {
    return muldiv(I64, balance, basis_points, 10_000 * 365, half_even);
}

// Apply one entry. Overdrawing is an expected error; overflow is a fault.
LedgerError!I64 apply(I64 balance, Entry e) {
    switch (e.kind) {
        case DEPOSIT:
            return balance + e.cents;
        case WITHDRAW:
            if (e.cents > balance) {
                return LedgerError.overdrawn;
            }
            return balance - e.cents;
        case INTEREST:
            return balance + daily_interest(balance, e.cents);
        default:
            return LedgerError.unknown_kind;
    }
}

void print_kind(U8 kind) {
    switch (kind) {
        case DEPOSIT: "deposit ";
        case WITHDRAW: "withdraw";
        case INTEREST: "interest";
        default: "unknown ";
    }
}

void main() {
    Entry[5] book;
    book[0] = Entry(DEPOSIT, 125_000);
    book[1] = Entry(WITHDRAW, 40_050);
    book[2] = Entry(INTEREST, 450);     // 4.50 percent a year, for one day
    book[3] = Entry(WITHDRAW, 200_000); // more than the balance: rejected
    book[4] = Entry(DEPOSIT, 99);
    I64 balance = 0;
    for i in 0..5 {
        Entry e = book[i];
        I64 next = apply(balance, e) catch (err) {
            switch (err) {
                case .overdrawn: "{i}: rejected, overdrawn\n";
                case .unknown_kind: "{i}: rejected, unknown kind\n";
            }
            continue;
        };
        balance = next;
        "{i}: ";
        print_kind(e.kind);
        " {e.cents:>8} -> {balance:/100}\n";
    }
    "final balance: {balance:/100}\n";
}

test "interest ties round to even" {
    assert(daily_interest(1_825_000, 1) == 0);  // exactly half a cent: rounds to 0
    assert(daily_interest(5_475_000, 1) == 2);  // exactly 1.5 cents: rounds to 2
}

test "an overdraft is an error" {
    I64 after = apply(100, Entry(WITHDRAW, 101)) catch -1;
    assert(after == -1);
}

test "an overflow is a fault" expect_fault E_OVERFLOW {
    _ = apply(I64.max, Entry(DEPOSIT, 1));
}
```

## the program

A sensor sends a temperature once a minute, in hundredths of a degree Celsius, and the program reports each day's low, high, mean and spread. The spread is the standard deviation: the square root of the mean of the squared distances from the mean.

```ci
// weather.ci: a month of temperature readings, one a minute,
// summarized day by day. A reading is in hundredths of a degree
// Celsius, as the sensor sends it.

const I64 DAYS = 30;
const I64 PER_DAY = 1_440;

// The reading at minute m of day d. It stands in for a file of real
// readings: a base that warms a little each day, a daily swing that
// peaks at 2 PM and a small, repeatable wobble.
I32 reading(I64 d, I64 m) {
    I64 base = 400 + 60 * d;
    I64 from_peak = m - 840;
    if (from_peak < 0) {
        from_peak = -from_peak;
    }
    I64 swing = 600 - from_peak * 600 / 720;
    I64 wobble = (d * PER_DAY + m) * 7_919 % 61 - 30;
    return (base + swing + wobble) as I32;
}

I32 sum_of_squares[n](in I32[n] xs) {
    I32 total = 0;
    for i in 0..n {
        total += xs[i] * xs[i];
    }
    return total;
}

void summarize(I64 d) {
    I32[1_440] day;
    I32 low = I32.max;
    I32 high = I32.min;
    I32 total = 0;
    for m in 0..PER_DAY {
        day[m] = reading(d, m);
        if (day[m] < low) {
            low = day[m];
        }
        if (day[m] > high) {
            high = day[m];
        }
        total += day[m];
    }
    I32 mean = total / 1_440;
    I32 variance = sum_of_squares(day) / 1_440 - mean * mean;
    I32 spread = isqrt(variance);
    "day {d:>2}: low {low:/100}, high {high:/100}, mean {mean:/100}, spread {spread:/100}\n";
}

void main() {
    for d in 1..=DAYS {
        summarize(d);
    }
}
```

`variance` uses the formula from statistics books: the mean of the squares, less the square of the mean.

### fix 1: a wider total

Make the total an `I64`, and square each reading as an `I64`:

```ci
I64 sum_of_squares[n](in I32[n] xs) {
    I64 total = 0;
    for i in 0..n {
        I64 x = xs[i] as I64;
        total += x * x;
    }
    return total;
}
```

In `summarize`, the variance becomes an `I64` too:

```ci
    I64 variance = sum_of_squares(day) / 1_440 - (mean as I64) * (mean as I64);
    I32 spread = isqrt(variance) as I32;
```

